        importAnnotations: function importAnnotations() {
            if (this.$els.annotationsfile.files.length === 0) {
                return;
            }
            var vm = this;
            var file = this.$els.annotationsfile.files[0];
            this.$els.annotationsfile.value = null;
            this.export.importVector(file, function (features, fileFormat) {
                var ignoredFeatures = [];
                var f = null;
                if (fileFormat === "gpx") {
                    //gpx file
                    for (var i = features.length - 1; i >= 0; i--) {
                        feature = features[i];
                        if (feature.getGeometry() instanceof _vendor.ol.geom.Point) {
                            //feature.set('toolName','Spot Fire')
                            ignoredFeatures.push(feature);
                            features.splice(i, 1);
                        } else if (feature.getGeometry() instanceof _vendor.ol.geom.LineString) {
                            vm.map.clearFeatureProperties(feature);
                            var coordinates = feature.getGeometry().getCoordinates();
                            coordinates.push(coordinates[0]);
                            feature.setGeometry(new _vendor.ol.geom.Polygon([coordinates]));
                            feature.set('toolName', 'Fire Boundary');
                        } else if (feature.getGeometry() instanceof _vendor.ol.geom.MultiLineString) {
                            //convert each linstring in MultiLineString as a fire boundary
                            vm.map.clearFeatureProperties(feature);
                            features.splice(i, 1);
                            var geom = feature.getGeometry();
                            var coordinates = null;
                            _vendor.$.each(geom.getLineStrings(), function (index, linestring) {
                                f = feature.clone();
                                coordinates = linestring.getCoordinates();
                                coordinates.push(coordinates[0]);
                                f.setGeometry(new _vendor.ol.geom.Polygon([coordinates]));
                                f.set('toolName', 'Fire Boundary');
                                features.splice(i, 0, f);
                            });
                        } else {
                            ignoredFeatures.push(feature);
                            features.splice(i, 1);
                        }
                    }
                } else {
                    //geo json file
                    for (var i = features.length - 1; i >= 0; i--) {
                        feature = features[i];
                        if (!vm.getTool(feature.get("toolName"))) {
                            // external feature.
                            if (feature.getGeometry() instanceof _vendor.ol.geom.Point) {
                                vm.map.clearFeatureProperties(feature);
                                feature.set('toolName', 'Custom Point', true);
                                feature.set('shape', vm.annotations.pointShapes[0][1], true);
                                feature.set('colour', "#000000", true);
                            } else if (feature.getGeometry() instanceof _vendor.ol.geom.LineString) {
                                vm.map.clearFeatureProperties(feature);
                                feature.set('toolName', 'Custom Line', true);
                                feature.set('size', 2, true);
                                feature.set('colour', "#000000", true);
                            } else if (feature.getGeometry() instanceof _vendor.ol.geom.Polygon) {
                                vm.map.clearFeatureProperties(feature);
                                feature.set('toolName', 'Custom Area', true);
                                feature.set('size', 2, true);
                                feature.set('colour', "#000000", true);
                            } else if (feature.getGeometry() instanceof _vendor.ol.geom.MultiPoint || feature.getGeometry() instanceof _vendor.ol.geom.MultiLineString || feature.getGeometry() instanceof _vendor.ol.geom.MultiPolygon || feature.getGeometry() instanceof _vendor.ol.geom.GeometryCollection) {
                                //remove the MultiPoint feature
                                features.splice(i, 1);
                                //split the gemoetry collection into mutiple features
                                var geometries = null;
                                if (feature.getGeometry() instanceof _vendor.ol.geom.MultiPoint) {
                                    geometries = feature.getGeometry().getPoints();
                                } else if (feature.getGeometry() instanceof _vendor.ol.geom.MultiLineString) {
                                    geometries = feature.getGeometry().getLineStrings();
                                } else if (feature.getGeometry() instanceof _vendor.ol.geom.MultiPolygon) {
                                    geometries = feature.getGeometry().getPolygons();
                                } else if (feature.getGeometry() instanceof _vendor.ol.geom.GeometryCollection) {
                                    geometries = feature.getGeometry().getGeometries();
                                }

                                //split MultiPoint to multiple point feature
                                _vendor.$.each(geometries, function (index, geometry) {
                                    f = new _vendor.ol.Feature({ geometry: geometry });
                                    features.splice(i, 0, f);
                                    i += 1;
                                });
                            } else {
                                ignoredFeatures.push(feature);
                                features.splice(i, 1);
                            }
                        }
                    }
                }
                if (ignoredFeatures.length) {
                    console.warn("The following features are ignored.\r\n" + vm.$root.geojson.writeFeatures(features));
                }
                if (features && features.length > 0) {
                    _vendor.$.each(features, function (index, feature) {
                        vm.drawingSequence += 1;
                        feature.set('id', vm.drawingSequence);
                        vm.initFeature(feature);
                    });
                    vm.features.extend(features);
                }
            });
        },
        downloadAnnotations: function downloadAnnotations(fmt) {
            this.$root.export.exportVector(this.features.getArray(), 'annotations', fmt);
        },
        getPerpendicular: function getPerpendicular(coords) {
            // find the nearest Polygon or lineString in the annotations layer
            var nearestFeature = gokart.annotations.featureOverlay.getSource().getClosestFeatureToCoordinate(coords, function (feat) {
                var geom = feat.getGeometry();
                return geom instanceof _vendor.ol.geom.Polygon || geom instanceof _vendor.ol.geom.LineString;
            });
            if (!nearestFeature) {
                // no feature == no rotation
                return 0.0;
            }
            var segments = [];
            var source = [];
            var segLength = 0;
            // if a Polygon, join the last segment to the first
            if (nearestFeature.getGeometry() instanceof _vendor.ol.geom.Polygon) {
                source = nearestFeature.getGeometry().getCoordinates()[0];
                segLength = source.length;
            } else {
                // if a LineString, don't include the last segment
                source = nearestFeature.getGeometry().getCoordinates();
                segLength = source.length - 1;
            }
            for (var i = 0; i < segLength; i++) {
                segments.push([source[i], source[(i + 1) % source.length]]);
            }
            // sort segments by ascending distance from point
            segments.sort(function (a, b) {
                return _vendor.ol.coordinate.squaredDistanceToSegment(coords, a) - _vendor.ol.coordinate.squaredDistanceToSegment(coords, b);
            });

            // head of the list is our target segment. reverse this to get the normal angle
            var offset = [segments[0][1][0] - segments[0][0][0], segments[0][1][1] - segments[0][0][1]];
            var normal = Math.atan2(-offset[1], offset[0]);
            return normal;
        },
