		getSiblingButtons: function getSiblingButtons(buttonElement) {
			var siblings = [];
			var sibling = buttonElement.parentNode.firstChild;
			while (sibling) {
				if (sibling.nodeType === 1 && sibling !== buttonElement) {
					siblings.push(sibling);
				}
				sibling = sibling.nextSibling;
			}
			return siblings;
		},

